//go:build lab

package main

import (
	"context"
	"fmt"
	"os"
	"os/signal"
	"syscall"

	"github.com/skenzeriq/activediq/internal/compose/server"
)

// Lab builds only (T-0855): `account add-passkey` stores the public half of a credential generated by the
// end-to-end suite's virtual authenticator. See internal/compose/server/labpasskey_lab.go.
func init() {
	labAccountCommand = func(name string, args []string) (int, bool) {
		if name != "add-passkey" {
			return 0, false
		}
		ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
		defer stop()
		if err := server.LabAddPasskey(ctx, args, os.Getenv, os.Stdout); err != nil {
			fmt.Fprintln(os.Stderr, err)
			return 1, true
		}
		return 0, true
	}
}
